css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .comp-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 8px 24px; margin-top: 4px;}
.mz .comp-fila{display: grid; grid-template-columns: 60px 60px 60px; gap: 8px; align-items: center; justify-content: center;}
.mz .comp-num{border: 2px solid var(--bosque); border-radius: 6px; height: 34px; display: flex; align-items: center; justify-content: center; font-family: sans-serif; font-size: 18px; font-weight: 800; background: #f0f0f0;}
.mz .comp-caja{border: 1.5px solid var(--bosque); border-radius: 6px; height: 34px;}
.mz .rodear-grid{display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px 18px; margin-top: 4px;}
.mz .rodear-fila{display: grid; grid-template-columns: 60px 60px; gap: 10px; justify-content: center;}
.mz .rodear-num{border: 2px solid var(--bosque); border-radius: 6px; height: 34px; display: flex; align-items: center; justify-content: center; font-family: sans-serif; font-size: 18px; font-weight: 800;}
.mz .ordenar-fila{padding: 4px 12px; border: 1.2px solid var(--bosque); border-radius: 6px; margin-bottom: 4px; font-size: 14px; font-weight: 600; display: flex; align-items: center; gap: 10px; flex-wrap: nowrap;}
.mz .ordenar-numeros{font-family: sans-serif; font-size: 16px; font-weight: 700;}
.mz .ordenar-cajas{display: flex; gap: 6px; flex: 1; justify-content: flex-end;}
.mz .ordenar-caja{border: 1.5px solid var(--bosque); border-radius: 6px; width: 50px; height: 28px;}
.mz .serie-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 8px 24px; margin-top: 4px;}
.mz .serie-fila{display: grid; grid-template-columns: 50px 50px 50px 50px 50px; gap: 4px; align-items: center; justify-content: center;}
.mz .serie-num{border: 2px solid var(--bosque); border-radius: 6px; height: 32px; display: flex; align-items: center; justify-content: center; font-family: sans-serif; font-size: 17px; font-weight: 800; background: #f0f0f0;}
.mz .serie-caja{border: 1.5px solid var(--bosque); border-radius: 6px; height: 32px;}
